<div class="table-scroll"><table><thead><tr><th>คำขอ / ผู้ติดต่อ</th><th>โปรแกรม</th><th>ผู้เดินทาง / ยอดรวม</th><th>สถานะ</th><th></th></tr></thead><tbody><?php foreach ($bookings as $b): ?><tr><td><b><?= e($b['reference']) ?></b><small><?= e($b['customer_name']) ?> · <?= e($b['phone']) ?></small></td><td><?= e($b['tour_title']) ?><small><?= thai_date($b['start_date']) ?></small><?php if (!empty($b['package_snapshot'])): ?><small>แพ็คเกจส่วนตัว · <?= e(json_decode($b['package_snapshot'],true)['level'] ?? '') ?></small><?php endif ?></td><td><?= (int)$b['traveler_count'] ?> คน<small>฿<?= money($b['total_price']) ?></small></td><td><span class="pill <?= e($b['status']) ?>"><?= status_label($b['status']) ?></span><?php if (!empty($b['pending_slips'])): ?><small><b>รอตรวจสลิป <?= (int)$b['pending_slips'] ?> รายการ</b></small><?php endif ?><?php if (isset($b['paid_amount'])): ?><small>ชำระแล้ว ฿<?= money($b['paid_amount']) ?></small><?php endif ?></td><td><a class="text-link" href="<?= (base_url() . ('admin/bookings/'.$b['id'])) ?>">เปิดคำขอ ↗</a></td></tr><?php endforeach ?><?php if (!$bookings): ?><tr><td colspan="5" class="empty">ยังไม่มีคำขอในรายการนี้</td></tr><?php endif ?></tbody></table></div>
